import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{@Test void publishedGroupsWithoutOrderingRestriction(){List<Integer>in=new ArrayList<>(List.of(4,1,3,2,3));TaskBinding.partition(in,3);assertEquals(5,in.size());assertEquals(Map.of(1,1,2,1,3,2,4,1),frequency(in));boolean upper=false;for(int v:in){if(v>3)upper=true;else assertFalse(upper);}}static Map<Integer,Integer>frequency(List<Integer>a){Map<Integer,Integer>counts=new HashMap<>();for(int v:a)counts.merge(v,1,Integer::sum);return counts;}}
